/** Shared decorative SVGs from approved V2.1. */
function ar_v21_icon($name, $extra='') {
    $paths = ['arrow-up-right'=>'<path d="M6 18 18 6M6 6h12v12"/>','arrow-right'=>'<path d="M4 12h16m-6-6 6 6-6 6"/>','arrow-left'=>'<path d="M20 12H4m6-6-6 6 6 6"/>','arrow-down'=>'<path d="M12 4v16m-6-6 6 6 6-6"/>','chevron'=>'<path d="m6 9 6 6 6-6"/>','menu'=>'<path d="M4 8h16"/><path d="M4 16h16"/>','search'=>'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4M8 10.5h5m-2.5-2.5v5"/>','users'=>'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m1 3a5 5 0 0 1 4 5v1"/>','compass'=>'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5L16 8Z"/>','brief'=>'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M9 5V3h6v2M8 10h8M8 14h8M8 18h5"/>','align'=>'<path d="M5 5h14M5 12h14M5 19h14"/><circle cx="9" cy="5" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="10" cy="19" r="2"/>','check'=>'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>','chat'=>'<path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-5 3v-3H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z"/><path d="M7 9h10M7 13h6"/>','book'=>'<path d="M12 5v15M3 4h4a6 6 0 0 1 5 2 6 6 0 0 1 5-2h4v15h-4a6 6 0 0 0-5 2 6 6 0 0 0-5-2H3V4Z"/>','list'=>'<path d="M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1"/>','info'=>'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>','target'=>'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="M12 2v3M22 12h-3M12 22v-3M2 12h3"/>','plus'=>'<path d="M5 12h14"/><path class="plus-vertical" d="M12 5v14"/>','route'=>'<path d="M6 5h9a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h9"/><circle cx="5" cy="5" r="2"/><path d="m16 18 3 3-3 3"/>'];
    if (!isset($paths[$name])) return '';
    return '<svg class="icon icon-'.esc_attr($name).' '.esc_attr($extra).'" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'.$paths[$name].'</svg>';
}
function ar_v21_badge($name) { return '<span class="concept-icon" aria-hidden="true">'.ar_v21_icon($name).'</span>'; }
